+//! Platform-acceptance contract types for the Twyne GPUI desktop port.
+//!
+//! These types describe *explicit, supported platform contracts* supplied as
+//! fixtures. They deliberately do not read the current implementation as the
+//! oracle: a fixture states what a supported linux/macOS/Windows distribution
+//! must declare, and verification compares an independently produced build
+//! receipt and distribution manifest against that stated contract.
+
+export type Platform = "linux" | "macos" | "windows";
+
+/** A helper executable the platform distribution must ship. */
+export interface HelperSpec {
+  /** Stable contract id, e.g. "document" or "math-write". */
+  id: string;
+  /** Base target name before any platform extension, e.g. "twyne-document". */
+  targetName: string;
+  /** Extension appended only on Windows, when the platform uses one. */
+  windowsExtension?: string;
+  /** Whether a complete distribution must contain this helper. */
+  required: boolean;
+}
+
+/** A key action whose aliases are part of the supported contract. */
+export interface KeyAliasSpec {
+  action: "save" | "undo" | "redo" | "quit";
+  /**
+   * Every alias the platform contract promises for this action. Verification
+   * requires each one to be observed in the build receipt.
+   */
+  aliases: string[];
+}
+
+/** A file association the distribution declares to the host OS. */
+export interface FileAssociationSpec {
+  /** Declared extension without a leading dot, e.g. "typ" or "twyne.json". */
+  extension: string;
+  mime: string;
+}
+
+/** A deep-link scheme the distribution declares. */
+export interface UrlSchemeSpec {
+  scheme: string;
+  /** Whether the contract claims startup handling inside the GPUI app. */
+  implementedInGpui: boolean;
+}
+
+/**
+ * Microphone metadata contract. A platform only requires usage-description
+ * metadata when a real hardware audio adapter is actually constructed.
+ */
+export interface MicrophoneContract {
+  /** Whether the platform contract requires microphone usage metadata. */
+  required: boolean;
+  /** Platform usage-description keys that would satisfy the requirement. */
+  usageKeys: string[];
+}
+
+/** A stated, supported platform contract loaded from a fixture. */
+export interface PlatformContract {
+  schemaVersion: number;
+  platform: Platform;
+  appId: string;
+  helpers: HelperSpec[];
+  keyAliases: KeyAliasSpec[];
+  fileAssociations: FileAssociationSpec[];
+  urlSchemes: UrlSchemeSpec[];
+  microphone: MicrophoneContract;
+}
+
+/** The subset of the staged distribution manifest this verification reads. */
+export interface DistributionManifest {
+  schemaVersion: number;
+  platform: Platform;
+  appId: string;
+  executables: { id: string; targetName: string; required: boolean }[];
+  files: { path: string; kind: string }[];
+}
+
+/** Independently observed build facts, not derived from the manifest. */
+export interface BuildReceipt {
+  platform: Platform;
+  /** Executable file names the build step actually produced. */
+  producedExecutables: string[];
+  /** Key bindings observed in the running build. */
+  keyBindings: { action: string; keystrokes: string[] }[];
+  startup: {
+    /** Whether a file-path argument is dispatched at startup. */
+    handlesFileArguments: boolean;
+    /** Whether a deep-link argument is dispatched at startup. */
+    handlesUrlScheme: boolean;
+    /** File-extension tokens the startup importer actually dispatches on. */
+    extensionTokens: string[];
+  };
+  microphone: {
+    /** Whether the build constructs a real hardware audio adapter. */
+    realAdapterPresent: boolean;
+    /** Usage-description keys actually present in the platform metadata. */
+    usageDescriptionKeys: string[];
+  };
+}
+
+export interface PlatformAcceptanceInput {
+  contract: PlatformContract;
+  manifest: DistributionManifest;
+  build: BuildReceipt;
+}
+
+/** Expected on-disk executable name for a helper on a platform. */
+export function expectedExecutableName(
+  helper: HelperSpec,
+  platform: Platform,
+): string {
+  return platform === "windows"
+    ? `${helper.targetName}${helper.windowsExtension ?? ""}`
+    : helper.targetName;
+}

