//! Deterministic packaging stage and verification for the native Twyne build.
//!
//! `stage` copies a release build (the desktop executable, the required Bun
//! helpers, original assets/licenses and platform bundle metadata) into an
//! isolated distribution tree and writes a manifest recording byte hashes.
//! `verify` re-reads that tree and fails on missing helpers, mismatched target
//! names, altered bytes, or absent notices.
//!
//! This tool only reads and writes files under the staging root. It never runs
//! Cargo, Devenv, a package manager, a signer, an installer, or the staged
//! binaries themselves, so a green run is *not* proof of a portable Linux
//! build, a clean install, macOS/Windows behavior, signing, or updates.

import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, rm, stat, writeFile } from "node:fs/promises";
import { dirname, join, posix, relative, resolve, sep } from "node:path";
import { readBinaryDependencies, type BinaryDependencies } from "./binary-deps";

const PACKAGING_ROOT = resolve(import.meta.dir);
const GPUI_ROOT = resolve(PACKAGING_ROOT, "..");

display.text:
//! Deterministic packaging stage and verification for the native Twyne build.
//!
//! `stage` copies a release build (the desktop executable, the required Bun
//! helpers, original assets/licenses and platform bundle metadata) into an
//! isolated distribution tree and writes a manifest recording byte hashes.
//! `verify` re-reads that tree and fails on missing helpers, mismatched target
//! names, altered bytes, or absent notices.
//!
//! This tool only reads and writes files under the staging root. It never runs
//! Cargo, Devenv, a package manager, a signer, an installer, or the staged
//! binaries themselves, so a green run is *not* proof of a portable Linux
//! build, a clean install, macOS/Windows behavior, signing, or updates.

import { createHash } from "node:crypto";
import { mkdir, readFile, readdir, rm, stat, writeFile } from "node:fs/promises";
import { dirname, join, posix, relative, resolve, sep } from "node:path";
import { readBinaryDependencies, type BinaryDependencies } from "./binary-deps";

const PACKAGING_ROOT = resolve(import.meta.dir);
const GPUI_ROOT = resolve(PACKAGING_ROOT, "..");
const REPOSITORY_ROOT = resolve(GPUI_ROOT, "../..");
const CONTRACT_PATH = join(PACKAGING_ROOT, "twyne-packaging.json");

export type Platform = "linux" | "macos" | "windows";

export interface ExecutableSpec {
  id: string;
  cargoBinary: string;
  targetName: string;
  required: boolean;
  /** Whether the application constructs this helper at runtime today. */
  wired: boolean;
  role: string;
  windowsExtension?: string;
  discovery?: string;
  wiringNote?: string;
}

export interface PathMapping {
  source: string;
  target: string;
}

interface Contract {
  schemaVersion: number;
  identifiers: Record<string, string>;
  executables: ExecutableSpec[];
  notices: { files: string[]; globs: string[] };
  platformMetadata: Record<Platform, PathMapping[]>;
  icons: Record<Platform, PathMapping[]>;
  fileAssociations: { extension: string; mime: string; description: string }[];
  launch: Record<string, unknown>;
  versions: Record<string, string>;
}

export interface StagedFile {
  /** POSIX path relative to the distribution root. */
  path: string;
  bytes: number;
  sha256: string;
  /** Where the file came from, relative to the repository root. */
  source: string;
  kind: "executable" | "metadata" | "icon" | "notice";
}

export interface StagedExecutable {
  id: string;
  /** POSIX path relative to the distribution root. */
  path: string;
  targetName: string;
  required: boolean;
  sha256: string;
  bytes: number;
  dependencies: BinaryDependencies;
}

export interface DistributionManifest {
  schemaVersion: number;
  generator: "desktop/gpui/packaging/stage.ts";
  platform: Platform;
  product: string;
  appId: string;
  nativeCrateVersion: string;
  productVersion: string;
  versionMismatch: boolean;
  executables: StagedExecutable[];
  files: StagedFile[];
}

export interface VerifyIssue {
  code:
    | "missing-executable"
    | "unexpected-target-name"
    | "hash-mismatch"
    | "missing-notice"
    | "missing-metadata"
    | "byte-count-mismatch"
    | "unexpected-file";
  detail: string;
  path?: string;
}

export interface VerifyResult {
  ok: boolean;
  issues: VerifyIssue[];
}

export function currentPlatform(): Platform {
  if (process.platform === "darwin") return "macos";
  if (process.platform === "win32") return "windows";
  return "linux";
}

function executableFileName(spec: ExecutableSpec, platform: Platform): string {
  return platform === "windows" ? `${spec.targetName}.exe` : spec.targetName;
}

function toPosix(value: string): string {
  return value.split(sep).join(posix.sep);
}

async function sha256File(path: string): Promise<{ sha256: string; bytes: number }> {
  const bytes = await readFile(path);
  return {
    sha256: createHash("sha256").update(bytes).digest("hex"),
    bytes: bytes.byteLength,
  };
}

async function expandGlobs(
  root: string,
  globs: string[],
): Promise<string[]> {
  const found: string[] = [];
  for (const pattern of globs) {
    const star = pattern.indexOf("*");
    if (star < 0) {
      found.push(pattern);
      continue;
    }
    const directory = pattern.slice(0, pattern.lastIndexOf("/", star));
    const suffix = pattern.slice(star + 1);
    const absolute = join(root, directory);
    let entries: string[];
    try {
      entries = await readdir(absolute);
    } catch {
      continue;
    }
    for (const entry of entries.sort()) {
      if (entry.endsWith(suffix)) found.push(posix.join(toPosix(directory), entry));
    }
  }
  return found;
}

export async function loadContract(path = CONTRACT_PATH): Promise<Contract> {
  return (await Bun.file(path).json()) as Contract;
}

export interface StageOptions {
  platform: Platform;
  /** Directory that holds the release binaries. */
  releaseDir: string;
  /** Destination distribution root (created/emptied). */
  outDir: string;
  productVersion?: string;
  nativeCrateVersion?: string;
}

async function readVersionFallback(options: StageOptions): Promise<{
  productVersion: string;
  nativeCrateVersion: string;
}> {
  const productVersion =
    options.productVersion ??
    (await Bun.file(join(REPOSITORY_ROOT, "package.json")).json()).version;
  const cargo = await Bun.file(join(GPUI_ROOT, "Cargo.toml")).text();
  const nativeCrateVersion =
    options.nativeCrateVersion ??
    (cargo.match(/^version\s*=\s*"([^"]+)"/m)?.[1] ?? "unknown");
  return { productVersion, nativeCrateVersion };
}

/** Stage a release build into an isolated distribution tree. */
export async function stage(options: StageOptions): Promise<DistributionManifest> {
  const contract = await loadContract();
  const { productVersion, nativeCrateVersion } = await readVersionFallback(options);
  const outDir = resolve(options.outDir);
  await rm(outDir, { recursive: true, force: true });
  await mkdir(outDir, { recursive: true });

  const files: StagedFile[] = [];
  const executables: StagedExecutable[] = [];

  const record = async (
    absoluteSource: string,
    target: string,
    kind: StagedFile["kind"],
  ): Promise<StagedFile> => {
    const destination = join(outDir, target);
    await mkdir(dirname(destination), { recursive: true });
    const bytes = await readFile(absoluteSource);
    await writeFile(destination, bytes);
    const digest = createHash("sha256").update(bytes).digest("hex");
    return {
      path: toPosix(target),
      bytes: bytes.byteLength,
      sha256: digest,
      source: toPosix(relative(REPOSITORY_ROOT, absoluteSource)),
      kind,
    };
  };

  for (const spec of contract.executables) {
    const name = executableFileName(spec, options.platform);
    const source = join(options.releaseDir, name);
    let present = true;
    try {
      present = (await stat(source)).isFile();
    } catch {
      present = false;
    }
    if (!present) {
      if (spec.required) {
        throw new Error(
          `Required helper "${spec.id}" is missing: expected ${source}. ` +
            `Build it with desktop.gpui.build-helper before staging.`,
        );
      }
      continue;
    }
    const file = await record(source, name, "executable");
    files.push(file);
    const bytes = await readFile(source);
    executables.push({
      id: spec.id,
      path: file.path,
      targetName: name,
      required: spec.required,
      sha256: file.sha256,
      bytes: file.bytes,
      dependencies: readBinaryDependencies(bytes),
    });
  }

  const noticePaths = [
    ...new Set([
      ...contract.notices.files,
      ...(await expandGlobs(GPUI_ROOT, contract.notices.globs)),
    ]),
  ].sort();
  for (const notice of noticePaths) {
    const source = join(GPUI_ROOT, notice);
    try {
      if (!(await stat(source)).isFile()) continue;
    } catch {
      continue;
    }
    files.push(await record(source, posix.join("share/doc/twyne", notice), "notice"));
  }

  for (const mapping of contract.platformMetadata[options.platform]) {
    const source = join(GPUI_ROOT, mapping.source);
    files.push(await record(source, mapping.target, "metadata"));
  }
  for (const mapping of contract.icons[options.platform]) {
    const source = join(GPUI_ROOT, mapping.source);
    files.push(await record(source, mapping.target, "icon"));
  }

  const manifest: DistributionManifest = {
    schemaVersion: contract.schemaVersion,
    generator: "desktop/gpui/packaging/stage.ts",
    platform: options.platform,
    product: "Twyne",
    appId: contract.identifiers.appId,
    nativeCrateVersion,
    productVersion,
    versionMismatch: nativeCrateVersion !== productVersion,
    executables,
    files: files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0)),
  };
  await writeFile(
    join(outDir, "distribution-manifest.json"),
    JSON.stringify(manifest, null, 2) + "\n",
  );
  return manifest;
}

/** Re-read a staged tree and report every concrete packaging defect. */
export async function verify(
  outDir: string,
  options: { manifest?: DistributionManifest } = {},
): Promise<VerifyResult> {
  const root = resolve(outDir);
  const contract = await loadContract();
  const manifest =
    options.manifest ??
    ((await Bun.file(join(root, "distribution-manifest.json")).json()) as DistributionManifest);
  const issues: VerifyIssue[] = [];
  const expected = new Set<string>(["distribution-manifest.json"]);

  for (const entry of manifest.executables) {
    expected.add(entry.path);
    const absolute = join(root, entry.path);
    let present = false;
    try {
      present = (await stat(absolute)).isFile();
    } catch {
      present = false;
    }
    if (!present) {
      issues.push({
        code: "missing-executable",
        path: entry.path,
        detail: `Staged executable "${entry.id}" is missing at ${entry.path}.`,
      });
      continue;
    }
    const spec = contract.executables.find((candidate) => candidate.id === entry.id);
    if (spec) {
      const wanted = executableFileName(spec, manifest.platform);
      if (entry.targetName !== wanted) {
        issues.push({
          code: "unexpected-target-name",
          path: entry.path,
          detail: `Executable "${entry.id}" staged as ${entry.targetName}, expected ${wanted} on ${manifest.platform}.`,
        });
      }
    }
    const digest = await sha256File(absolute);
    if (digest.sha256 !== entry.sha256) {
      issues.push({
        code: "hash-mismatch",
        path: entry.path,
        detail: `Staged bytes changed for ${entry.path}: ${entry.sha256} -> ${digest.sha256}.`,
      });
    }
    if (digest.bytes !== entry.bytes) {
      issues.push({
        code: "byte-count-mismatch",
        path: entry.path,
        detail: `Staged size changed for ${entry.path}: ${entry.bytes} -> ${digest.bytes}.`,
      });
    }
  }

  for (const spec of contract.executables) {
    if (!spec.required) continue;
    const name = executableFileName(spec, manifest.platform);
    if (!manifest.executables.some((entry) => entry.targetName === name)) {
      issues.push({
        code: "missing-executable",
        path: name,
        detail: `Required helper "${spec.id}" (${name}) is not in the staged manifest.`,
      });
    }
  }

  for (const file of manifest.files) {
    expected.add(file.path);
    const absolute = join(root, file.path);
    let present = false;
    try {
      present = (await stat(absolute)).isFile();
    } catch {
      present = false;
    }
    if (!present) {
      issues.push({
        code: "missing-metadata",
        path: file.path,
        detail: `Staged file is missing: ${file.path}.`,
      });
      continue;
    }
    const digest = await sha256File(absolute);
    if (digest.sha256 !== file.sha256) {
      issues.push({
        code: "hash-mismatch",
        path: file.path,
        detail: `Staged bytes changed for ${file.path}.`,
      });
    }
  }

  const stagedNotices = manifest.files.filter((file) => file.kind === "notice");
  if (stagedNotices.length === 0) {
    issues.push({
      code: "missing-notice",
      detail: "No license or notice files were staged.",
    });
  }
  const hasNoticeDoc = stagedNotices.some((file) => file.path.endsWith("assets/NOTICE.md"));
  if (!hasNoticeDoc) {
    issues.push({
      code: "missing-notice",
      detail: "assets/NOTICE.md is not staged; original asset provenance would be lost.",
    });
  }

  for (const mapping of [
    ...contract.platformMetadata[manifest.platform],
    ...contract.icons[manifest.platform],
  ]) {
    if (!manifest.files.some((file) => file.path === mapping.target)) {
      issues.push({
        code: "missing-metadata",
        path: mapping.target,
        detail: `Platform bundle metadata ${mapping.target} was not staged for ${manifest.platform}.`,
      });
    }
  }

  for await (const path of walk(root)) {
    if (!expected.has(path)) {
      issues.push({
        code: "unexpected-file",
        path,
        detail: `Unexpected file in the distribution tree: ${path}.`,
      });
    }
  }

  return { ok: issues.length === 0, issues };
}

async function* walk(root: string, prefix = ""): AsyncGenerator<string> {
  const entries = await readdir(join(root, prefix), { withFileTypes: true });
  for (const entry of entries.sort((a, b) => (a.name < b.name ? -1 : 1))) {
    const relativePath = prefix ? posix.join(prefix, entry.name) : entry.name;
    if (entry.isDirectory()) {
      yield* walk(root, relativePath);
    } else {
      yield relativePath;
    }
  }
}

interface CliArgs {
  command: "stage" | "verify";
  platform: Platform;
  releaseDir: string;
  outDir: string;
}

function parseArgs(argv: string[]): CliArgs {
  const [command, ...rest] = argv;
  if (command !== "stage" && command !== "verify") {
    throw new Error("Usage: stage.ts <stage|verify> [--platform ...] [--release ...] [--out ...]");
  }
  let platform = currentPlatform();
  let releaseDir = join(GPUI_ROOT, "target", "release");
  let outDir = join(GPUI_ROOT, "target", "distribution");
  for (let index = 0; index < rest.length; index += 1) {
    const flag = rest[index];
    const value = rest[index + 1];
    if (flag === "--platform" && value) {
      if (value !== "linux" && value !== "macos" && value !== "windows") {
        throw new Error(`Unknown platform: ${value}`);
      }
      platform = value;
      index += 1;
    } else if (flag === "--release" && value) {
      releaseDir = resolve(value);
      index += 1;
    } else if (flag === "--out" && value) {
      outDir = resolve(value);
      index += 1;
    }
  }
  return { command, platform, releaseDir, outDir };
}

if (import.meta.main) {
  const args = parseArgs(process.argv.slice(2));
  if (args.command === "stage") {
    const manifest = await stage({
      platform: args.platform,
      releaseDir: args.releaseDir,
      outDir: args.outDir,
    });
    const helpers = manifest.executables.map((entry) => entry.targetName).join(", ");
    console.log(`Staged ${manifest.files.length} files for ${manifest.platform}: ${helpers}`);
    if (manifest.versionMismatch) {
      console.log(
        `Version note: crate ${manifest.nativeCrateVersion} vs product ${manifest.productVersion}.`,
      );
    }
  } else {
    const result = await verify(args.outDir);
    if (result.ok) {
      console.log("Distribution verification passed.");
    } else {
      for (const issue of result.issues) {
        console.error(`[${issue.code}] ${issue.detail}`);
      }
      process.exitCode = 1;
    }
  }
}

