//! Platform-acceptance contract types for the Twyne GPUI desktop port.
//!
//! These types describe *explicit, supported platform contracts* supplied as
//! fixtures. They deliberately do not read the current implementation as the
//! oracle: a fixture states what a supported linux/macOS/Windows distribution
//! must declare, and verification compares an independently produced build
//! receipt and distribution manifest against that stated contract.

export type Platform = "linux" | "macos" | "windows";

/** A helper executable the platform distribution must ship. */
export interface HelperSpec {
  /** Stable contract id, e.g. "document" or "math-write". */
  id: string;
  /** Base target name before any platform extension, e.g. "twyne-document". */
  targetName: string;
  /** Extension appended only on Windows, when the platform uses one. */
  windowsExtension?: string;
  /** Whether a complete distribution must contain this helper. */
  required: boolean;
}

/** A key action whose aliases are part of the supported contract. */
export interface KeyAliasSpec {
  action: "save" | "undo" | "redo" | "quit";
  /**
   * Every alias the platform contract promises for this action. Verification
   * requires each one to be observed in the build receipt.
   */
  aliases: string[];
}

/** A file association the distribution declares to the host OS. */
export interface FileAssociationSpec {
  /** Declared extension without a leading dot, e.g. "typ" or "twyne.json". */
  extension: string;
  mime: string;
}

/** A deep-link scheme the distribution declares. */
export interface UrlSchemeSpec {
  scheme: string;
  /** Whether the contract claims startup handling inside the GPUI app. */
  implementedInGpui: boolean;
}

/**
 * Microphone metadata contract. A platform only requires usage-description
 * metadata when a real hardware audio adapter is actually constructed.
 */
export interface MicrophoneContract {
  /** Whether the platform contract requires microphone usage metadata. */
  required: boolean;
  /** Platform usage-description keys that would satisfy the requirement. */
  usageKeys: string[];
}

/** A stated, supported platform contract loaded from a fixture. */
export interface PlatformContract {
  schemaVersion: number;
  platform: Platform;
  helpers: HelperSpec[];
  keyAliases: KeyAliasSpec[];
  fileAssociations: FileAssociationSpec[];
  urlSchemes: UrlSchemeSpec[];
  microphone: MicrophoneContract;
}

/** The subset of the staged distribution manifest this verification reads. */
export interface DistributionManifest {
  schemaVersion: number;
  platform: Platform;
  appId: string;
  executables: { id: string; targetName: string; required: boolean }[];
  files: { path: string; kind: string }[];
}

/** Independently observed build facts, not derived from the manifest. */
export interface BuildReceipt {
  platform: Platform;
  /** Executable file names the build step actually produced. */
  producedExecutables: string[];
  /** Key bindings observed in the running build. */
  keyBindings: { action: string; keystrokes: string[] }[];
  startup: {
    /** Whether a file-path argument is dispatched at startup. */
    handlesFileArguments: boolean;
    /** Whether a deep-link argument is dispatched at startup. */
    handlesUrlScheme: boolean;
    /** File-extension tokens the startup importer actually dispatches on. */
    extensionTokens: string[];
  };
  microphone: {
    /** Whether the build constructs a real hardware audio adapter. */
    realAdapterPresent: boolean;
    /** Usage-description keys actually present in the platform metadata. */
    usageDescriptionKeys: string[];
  };
}

export interface PlatformAcceptanceInput {
  contract: PlatformContract;
  manifest: DistributionManifest;
  build: BuildReceipt;
}

/** Expected on-disk executable name for a helper on a platform. */
export function expectedExecutableName(
  helper: HelperSpec,
  platform: Platform,
): string {
  return platform === "windows"
    ? `${helper.targetName}${helper.windowsExtension ?? ""}`
    : helper.targetName;
}

//! Platform-acceptance verification for the Twyne GPUI desktop port.
//!
//! This tool accepts three explicit inputs — a supported platform contract, a
//! staged distribution manifest, and an independently produced build receipt —
//! and reports concrete deployment-critical mismatches. It never treats the
//! current source implementation as the oracle: the contract fixtures state
//! what a supported linux/macOS/Windows distribution must declare, and the
//! build receipt states what the build step actually produced.
//!
//! Scope boundaries, stated honestly:
//!   - A green run proves only that the three supplied inputs agree. It is not
//!     proof of macOS or Windows device behavior, signing, notarization,
//!     installers, updates, or a clean-machine run.
//!   - IME composition, clipboard transfer, and accessibility-tree behavior are
//!     NOT verified here and are reported as `unproven`. They remain unproven
//!     unless a cited device receipt exists elsewhere.
//!   - Microphone metadata is required only when the build receipt shows a real
//!     hardware audio adapter is constructed. Mock/abstract backends need none.

import {
  expectedExecutableName,
  type BuildReceipt,
  type Platform,
  type PlatformAcceptanceInput,
  type PlatformContract,
} from "./contract";

export type AcceptanceIssueCode =
  | "platform-mismatch"
  | "app-id-mismatch"
  | "missing-helper"
  | "unexpected-helper-name"
  | "missing-key-alias"
  | "unhandled-association"
  | "undeclared-association"
  | "unimplemented-url-scheme"
  | "unsupported-microphone-requirement"
  | "missing-microphone-contract"
  | "missing-microphone-metadata";

export interface AcceptanceIssue {
  code: AcceptanceIssueCode;
  detail: string;
}

export interface AcceptanceResult {
  ok: boolean;
  issues: AcceptanceIssue[];
  /** Platform behaviors this verifier deliberately does not prove. */
  unproven: string[];
}

const UNPROVEN = [
  "IME composition and candidate handling",
  "clipboard read/write across applications",
  "accessibility tree and screen-reader behavior",
  "macOS/Windows real-device execution",
];

function normalizeExtension(extension: string): string {
  return extension.replace(/^\./, "").toLowerCase();
}

export function verifyPlatformAcceptance(
  input: PlatformAcceptanceInput,
): AcceptanceResult {
  const { contract, manifest, build } = input;
  const issues: AcceptanceIssue[] = [];

  if (contract.platform !== manifest.platform) {
    issues.push({
      code: "platform-mismatch",
      detail: `Contract platform ${contract.platform} does not match manifest platform ${manifest.platform}.`,
    });
  }
  if (contract.platform !== build.platform) {
    issues.push({
      code: "platform-mismatch",
      detail: `Contract platform ${contract.platform} does not match build receipt platform ${build.platform}.`,
    });
  }

  verifyHelpers(contract, manifest, build, issues);
  verifyKeyAliases(contract, build, issues);
  verifyAssociations(contract, build, issues);
  verifyMicrophone(contract, build, issues);

  return { ok: issues.length === 0, issues, unproven: [...UNPROVEN] };
}

function verifyHelpers(
  contract: PlatformContract,
  manifest: PlatformAcceptanceInput["manifest"],
  build: BuildReceipt,
  issues: AcceptanceIssue[],
): void {
  const platform = contract.platform;
  const staged = new Set(manifest.executables.map((entry) => entry.targetName));
  const produced = new Set(build.producedExecutables);

  for (const helper of contract.helpers) {
    const wanted = expectedExecutableName(helper, platform);
    const inManifest = staged.has(wanted);
    const inBuild = produced.has(wanted);
    if (helper.required && !inManifest) {
      issues.push({
        code: "missing-helper",
        detail: `Required helper "${helper.id}" (${wanted}) is absent from the staged manifest for ${platform}.`,
      });
    }
    if (helper.required && !inBuild) {
      issues.push({
        code: "missing-helper",
        detail: `Required helper "${helper.id}" (${wanted}) was not produced by the build receipt for ${platform}.`,
      });
    }
  }

  for (const entry of manifest.executables) {
    const helper = contract.helpers.find((spec) => spec.id === entry.id);
    if (!helper) {
      issues.push({
        code: "unexpected-helper-name",
        detail: `Staged executable "${entry.id}" has no contract entry.`,
      });
      continue;
    }
    const wanted = expectedExecutableName(helper, platform);
    if (entry.targetName !== wanted) {
      issues.push({
        code: "unexpected-helper-name",
        detail: `Helper "${helper.id}" staged as ${entry.targetName}, contract expects ${wanted} on ${platform}.`,
      });
    }
    if (entry.required !== helper.required) {
      issues.push({
        code: "unexpected-helper-name",
        detail: `Helper "${helper.id}" required=${entry.required} disagrees with contract required=${helper.required}.`,
      });
    }
  }
}

function verifyKeyAliases(
  contract: PlatformContract,
  build: BuildReceipt,
  issues: AcceptanceIssue[],
): void {
  for (const spec of contract.keyAliases) {
    const observed = new Set(
      build.keyBindings
        .filter((binding) => binding.action === spec.action)
        .flatMap((binding) => binding.keystrokes),
    );
    for (const alias of spec.aliases) {
      if (!observed.has(alias)) {
        issues.push({
          code: "missing-key-alias",
          detail: `Action "${spec.action}" is missing promised alias "${alias}" on ${contract.platform}.`,
        });
      }
    }
  }
}

function verifyAssociations(
  contract: PlatformContract,
  build: BuildReceipt,
  issues: AcceptanceIssue[],
): void {
  const declared = new Set(
    contract.fileAssociations.map((entry) => normalizeExtension(entry.extension)),
  );
  const handled = new Set(
    build.startup.extensionTokens.map((token) => normalizeExtension(token)),
  );

  for (const extension of declared) {
    if (!handled.has(extension)) {
      issues.push({
        code: "unhandled-association",
        detail: `Declared file association ".${extension}" is not dispatched by startup handling on ${contract.platform}.`,
      });
    }
  }
  for (const extension of handled) {
    if (!declared.has(extension)) {
      issues.push({
        code: "undeclared-association",
        detail: `Startup dispatches ".${extension}" which is not a declared file association on ${contract.platform}.`,
      });
    }
  }

  for (const scheme of contract.urlSchemes) {
    if (scheme.implementedInGpui && !build.startup.handlesUrlScheme) {
      issues.push({
        code: "unimplemented-url-scheme",
        detail: `Scheme "${scheme.scheme}" claims GPUI startup handling but the build receipt shows none on ${contract.platform}.`,
      });
    }
  }
}

function verifyMicrophone(
  contract: PlatformContract,
  build: BuildReceipt,
  issues: AcceptanceIssue[],
): void {
  const { realAdapterPresent, usageDescriptionKeys } = build.microphone;
  if (!realAdapterPresent) {
    if (contract.microphone.required) {
      issues.push({
        code: "unsupported-microphone-requirement",
        detail: `Contract requires microphone metadata on ${contract.platform}, but no real hardware audio adapter is constructed.`,
      });
    }
    return;
  }
  if (!contract.microphone.required) {
    issues.push({
      code: "missing-microphone-contract",
      detail: `A real hardware audio adapter is constructed on ${contract.platform}, but the contract does not require microphone metadata.`,
    });
  }
  const hasUsageKey = contract.microphone.usageKeys.some((key) =>
    usageDescriptionKeys.includes(key),
  );
  if (!hasUsageKey) {
    issues.push({
      code: "missing-microphone-metadata",
      detail: `A real audio adapter needs microphone usage metadata (${contract.microphone.usageKeys.join(", ")}) on ${contract.platform}.`,
    });
  }
}

export function formatAcceptanceResult(result: AcceptanceResult): string {
  const lines = result.ok ? ["Platform acceptance verification passed."] : ["Platform acceptance verification failed."];
  for (const issue of result.issues) lines.push(`[${issue.code}] ${issue.detail}`);
  for (const item of result.unproven) lines.push(`[unproven] ${item}`);
  return lines.join("\n");
}

if (import.meta.main) {
  const path = process.argv[2];
  if (!path) {
    console.error("Usage: verify.ts <platform-acceptance-input.json>");
    process.exitCode = 2;
  } else {
    const input = (await Bun.file(path).json()) as PlatformAcceptanceInput;
    const result = verifyPlatformAcceptance(input);
    console.log(formatAcceptanceResult(result));
    if (!result.ok) process.exitCode = 1;
  }
}

